No existing project. Create web app with confirmation modal?

```html
<!DOCTYPE html>
<html>
<head>
  <title>Delete Confirmation Modal</title>
  <style>
    body { font-family: Arial; margin: 20px; }
    .item { padding: 10px; border: 1px solid #ddd; margin: 10px 0; }
    .item button { background: red; color: white; padding: 5px 10px; border: none; cursor: pointer; }

    .modal { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); }
    .modal.active { display: flex; align-items: center; justify-content: center; }
    .modal-content { background: white; padding: 30px; border-radius: 8px; text-align: center; }
    .modal-buttons { margin-top: 20px; }
    .modal-buttons button { margin: 0 10px; padding: 8px 20px; cursor: pointer; }
    .confirm { background: red; color: white; }
    .cancel { background: gray; color: white; }
  </style>
</head>
<body>
  <h1>Items</h1>
  <div id="items-container"></div>

  <div id="modal" class="modal">
    <div class="modal-content">
      <p>Delete this item?</p>
      <div class="modal-buttons">
        <button class="confirm" id="confirm-delete">Delete</button>
        <button class="cancel" id="cancel-delete">Cancel</button>
      </div>
    </div>
  </div>

  <script>
    const items = ['Item 1', 'Item 2', 'Item 3'];
    let itemToDelete = null;

    function renderItems() {
      const container = document.getElementById('items-container');
      container.innerHTML = items.map((item, idx) => `
        <div class="item">
          ${item}
          <button onclick="showDeleteModal(${idx})">Delete</button>
        </div>
      `).join('');
    }

    function showDeleteModal(idx) {
      itemToDelete = idx;
      document.getElementById('modal').classList.add('active');
    }

    function hideModal() {
      document.getElementById('modal').classList.remove('active');
      itemToDelete = null;
    }

    document.getElementById('confirm-delete').addEventListener('click', () => {
      items.splice(itemToDelete, 1);
      hideModal();
      renderItems();
    });

    document.getElementById('cancel-delete').addEventListener('click', hideModal);

    renderItems();
  </script>
</body>
</html>
```

Vanilla JS modal with confirm/cancel buttons. Modal overlay. Click delete button → shows modal → confirm deletes item. Save as `index.html`, open in browser.
